const crypto = require('crypto');
const body = $input.first().json.body || {};
const auth = $input.first().json.headers?.authorization || '';
const token = auth.startsWith('Bearer ') ? auth.slice(7) : '';
const deviceId = body.deviceId || '';
if (!token || !deviceId) throw new Error('missing credentials');
// Per-device token validation: hash the presented token and compare against the
// stored hash for this deviceId. The store is a small HTTP endpoint (DEVICE_TOKENS_URL)
// backed by Postgres/Redis. Falls back to a single shared env token for dev.
const sha = crypto.createHash('sha256').update(token).digest('hex');
let expected;
if ($env.DEVICE_TOKENS_URL) {
  // Synchronous fetch is not available in n8n function nodes; in production use an
  // HTTP Request node before this one to fetch the hash, then compare here.
  // For now we expect the hash to have been injected by a prior 'Fetch Token Hash' node.
  expected = $('Fetch Token Hash').item.json.hash;
} else {
  expected = crypto.createHash('sha256').update($env.ULTRON_DEVICE_TOKEN).digest('hex');
}
if (expected !== sha) throw new Error('unauthorized: device token mismatch');
return $input.all();

const raw = $input.first().json.message?.content ?? $input.first().json;
let p; try { p = JSON.parse(raw); } catch { p = { intent: 'general.chat', confidence: 0.5, args: {} }; }
if (p.confidence < 0.5) p.intent = 'general.chat';
return [{ json: p }];
